public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File is null.");
    }
    // The getAbsolutePath() method returns the absolute path of the file, in case the input file is a symbolic link.
    String filePath = file.getAbsolutePath();
    // The deleteOnExit() method is called to schedule the deletion of the file when the JVM exits.
    file.deleteOnExit();
    // The isDirectory() method checks if the input file is a directory, and the if statement is used to ensure that the file and its sub-directories are deleted if it is a directory.
    if (file.isDirectory()) {
        // The listFiles() method returns an array of files and sub-directories in the directory, which are then iterated over using a for loop.
        File[] files = file.listFiles();
        for (File fileToDelete : files) {
            // Recursively call the forceDeleteOnExit() method to delete the current file or sub-directory, and any files or sub-directories it may contain.
            forceDeleteOnExit(fileToDelete);
        }
    }
}

