    if (!target.isBipartite()) {
        throw new IllegalArgumentException("The target graph is not bipartite");
    }

    // Compute the number of vertices in the source graph
    int numVertices = resultMap.size();

    // Construct a new bipartite graph with the same number of vertices
    Graph<V, E> bipartiteGraph = new Graph<>(numVertices * 2);

    // Add vertices to the bipartite graph
    for (String vertex : resultMap.keySet()) {
        int index = Integer.parseInt(vertex);
        int newIndex = index / 2;
        V originalVertex = resultMap.get(vertex);
        bipartiteGraph.addVertex(newIndex, originalVertex);
    }

    // Add edges to the bipartite graph
    for (String edge : resultMap.keySet()) {
        int index = Integer.parseInt(edge);
        int newIndex = index / 2;
        V leftVertex = resultMap.get(edge + "L");
        V rightVertex = resultMap.get(edge + "R");
        bipartiteGraph.addEdge(newIndex, leftVertex, rightVertex);
    }

    // Set the resulting bipartite graph
    this.resultGraph = bipartiteGraph;
}

public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    int numVertices = target.getNumVertices();
    int numEdges = target.getNumEdges();

    // Create vertices
    for (int i = 0; i < numVertices; i++) {
        String v = "V" + i;
        V vertex = new V();
        resultMap.put(v, vertex);
        target.addVertex(vertex);
    }

    // Create edges
    for (int i = 0; i < numEdges; i++) {
        String v = "E" + i;
        E edge = new E();
        resultMap.put(v, edge);
        target.addEdge(edge);
    }

    // Set bipartite status
    for (int i = 0; i < numEdges; i++) {
        String v = "E" + i;
        E edge = resultMap.get(v);
        int sourceIndex = i % numVertices;
        int targetIndex = (i + 1) % numVertices;
        V source = resultMap.get("V" + sourceIndex);
        V target = resultMap.get("V" + targetIndex);
        target.addEdge(edge, source, target);
    }

    // Set edge properties
    for (int i = 0; i < numEdges; i++) {
        String v = "E" + i;
        E edge = resultMap.get(v);
        edge.setProperty("weight", 1);
    }
}

private void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Step 1: Create the bipartite graph
    Graph<V, E> bipartiteGraph = new Graph<>();

    // Step 2: Add vertices to the graph
    for (String vertexLabel : resultMap.keySet()) {
        V vertex = resultMap.get(vertexLabel);
        bipartiteGraph.addVertex(vertex);
    }

    // Step 3: Add edges to the graph
    for (int i = 0; i < resultMap.size() - 1; i++) {
        for (int j = i + 1; j < resultMap.size(); j++) {
            V vi = resultMap.get(resultMap.keySet().toArray()[i]);
            V vj = resultMap.get(resultMap.keySet().toArray()[j]);
            E edge = new E(vi, vj);
            bipartiteGraph.addEdge(edge);
        }
    }

    // Step 4: Copy the graph to the target
    for (V vertex : bipartiteGraph.getVertices()) {
        target.addVertex(vertex);
    }
    for (E edge : bipartiteGraph.getEdges()) {
        target.addEdge(edge);
    }
}

