}

public static int writeDelimitedTo(OutputStream out, Object message, Schema schema, LinkedBuffer buffer) throws IOException {
    // 1. Write the size of the message to the output stream
    ByteBuffer code = code(message, schema, buffer);
    int length = code.remaining();
    out.write(length >> 24 & 0xFF);
    out.write(length >> 16 & 0xFF);
    out.write(length >> 8 & 0xFF);
    out.write(length & 0xFF);

    // 2. Write the message to the output stream
    out.write(code.array(), 0, code.limit());

    return length;
}

public static ByteBuffer code(Object message, Schema schema, LinkedBuffer buffer) {
    // 1. Allocate space for the message
    int size = schema.getSize(message, buffer);
    ByteBuffer code = ByteBuffer.allocate(size + 1);

    // 2. Write the message
    schema.writeTo(message, buffer, code);

    // 3. Write the type ID
    code.put((byte) schema.getTypeId());

    return code;
}

