    int totalContentSize = 0;

    // Write out the nodes in the LinkedBuffer
    for (LinkedNode<Object[]> currentNode = node.head; currentNode != null; currentNode = currentNode.next) {
        // Get the current node's content
        Object[] content = currentNode.val;

        // Write out the content length
        int contentLength = content.length;
        out.writeInt(contentLength);

        // Write out the content
        for (Object obj : content) {
            if (obj instanceof Integer) {
                out.writeInt((Integer) obj);
            } else if (obj instanceof String) {
                out.writeUTF((String) obj);
            } else if (obj instanceof Double) {
                out.writeDouble((Double) obj);
            }
        }

        // Update the total content size
        totalContentSize += contentLength;
    }

    return totalContentSize;
}

