public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {

  // Check if the buffer is empty
  if (node == null) {
      return 0;
  }

  // Write the contents of the buffer to the output
  int totalSize = 0;
  do {
      int remaining = node.getRemaining();
      out.write(node.getBuffer(), 0, remaining);
      totalSize += remaining;
      node = node.getNext();
  } while (node != null);

  return totalSize;
}

