    // Create a new graph path
    GraphPath<V,E> path = new GraphPath<V,E>(graph);

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the source and target vertices of the current edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add the edge to the path
        path.addEdge(edge);

        // Add the source vertex to the path if it is not already in the path
        if (!path.containsVertex(source)) {
            path.addVertex(source);
        }

        // Add the target vertex to the path if it is not already in the path
        if (!path.containsVertex(target)) {
            path.addVertex(target);
        }
    }

    // Return the transformed graph path
    return path;
}

