     * expression pattern to match.
     *
     * @param level     the logging level to return if a match is found
     * @param pattern   the regular expression pattern to match
     */
    public CustomFilter(int level, String pattern) {
        this.level = level;
        this.pattern = pattern;
    }

    /**
     * Returns {@link Filter#NEUTRAL} if the logging event's message does not match
     * the regular expression pattern, or the {@link CustomFilter#level} if a match
     * is found.
     *
     * @param event the logging event to evaluate
     * @return the logging level to return
     */
    public int decide(LoggingEvent event) {
        String message = event.getMessage();
        if (message.matches(pattern)) {
            return level;
        }
        return Filter.NEUTRAL;
    }
}

