public static String applyRelativePath(String path, String relativePath) {
    // Split the path into a list of folder names
    List<String> pathFolders = Arrays.asList(path.split("/"));
    // Split the relative path into a list of folder names
    List<String> relativePathFolders = Arrays.asList(relativePath.split("/"));
    // Build a new list of folder names by combining the two lists
    List<String> newPathFolders = new ArrayList<>();
    for (String folder : pathFolders) {
        newPathFolders.add(folder);
    }
    for (String folder : relativePathFolders) {
        if (folder.equals("..")) {
            // If the folder is "..", remove the last folder from the new path
            newPathFolders.remove(newPathFolders.size() - 1);
        } else if (!folder.equals(".")) {
            // If the folder is not "." or "..", add it to the new path
            newPathFolders.add(folder);
        }
    }
    // Join the new folder names into a single path string
    String newPath = String.join("/", newPathFolders);
    return newPath;
}

